import React, { useState, useMemo } from 'react';
import './EquipmentTable.css';

function EquipmentTable({ equipment, onEdit, onDelete }) {
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState('');
  const [sortField, setSortField] = useState('last_cleaned_date');
  const [sortDirection, setSortDirection] = useState('asc');

  const filteredAndSortedEquipment = useMemo(() => {
    if (!equipment || equipment.length === 0) {
      return [];
    }

    let filtered = equipment.filter(eq => {
      if (!eq) return false;

      const matchesSearch = !searchTerm || 
        (eq.name && eq.name.toLowerCase().includes(searchTerm.toLowerCase()));
      const matchesType = !typeFilter || eq.type === typeFilter;

      return matchesSearch && matchesType;
    });

    filtered.sort((a, b) => {
      let aVal = a[sortField];
      let bVal = b[sortField];

      if (sortField === 'last_cleaned_date') {
        aVal = new Date(aVal);
        bVal = new Date(bVal);
      } else {
        aVal = String(aVal || '').toLowerCase();
        bVal = String(bVal || '').toLowerCase();
      }

      if (sortDirection === 'asc') {
        return aVal > bVal ? 1 : aVal < bVal ? -1 : 0;
      } else {
        return aVal < bVal ? 1 : aVal > bVal ? -1 : 0;
      }
    });

    return filtered;
  }, [equipment, searchTerm, typeFilter, sortField, sortDirection]);

  const handleSort = (field) => {
    if (field === 'last_cleaned_date') {
      if (sortField === field) {
        setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
      } else {
        setSortField(field);
        setSortDirection('asc');
      }
    }
  };

  return (
    <div className="equipment-table-container">
      <div className="table-controls">
        <div className="search-filter-group">
          <div className="search-box">
            <label htmlFor="search">Search by Name:</label>
            <input
              type="text"
              id="search"
              placeholder="Enter equipment name..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="filter-box">
            <label htmlFor="typeFilter">Filter by Type:</label>
            <select
              id="typeFilter"
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
            >
              <option value="">All Types</option>
              <option value="Machine">Machine</option>
              <option value="Vessel">Vessel</option>
              <option value="Tank">Tank</option>
              <option value="Mixer">Mixer</option>
            </select>
          </div>
        </div>
      </div>

      {filteredAndSortedEquipment.length === 0 ? (
        <div className="no-results">No equipment found.</div>
      ) : (
        <div className="table-wrapper">
          <table className="equipment-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Type</th>
                <th>Status</th>
                <th 
                  className="sortable"
                  onClick={() => handleSort('last_cleaned_date')}
                >
                  Last Cleaned Date
                  {sortField === 'last_cleaned_date' && (
                    <span className="sort-indicator">
                      {sortDirection === 'asc' ? ' ↑' : ' ↓'}
                    </span>
                  )}
                </th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredAndSortedEquipment.map(eq => (
                <tr key={eq.id}>
                  <td>{eq.id}</td>
                  <td>{eq.name}</td>
                  <td>{eq.type}</td>
                  <td>
                    <span className={`status-badge status-${eq.status.toLowerCase().replace(' ', '-')}`}>
                      {eq.status}
                    </span>
                  </td>
                  <td>{new Date(eq.last_cleaned_date).toLocaleDateString()}</td>
                  <td>
                    <button 
                      className="edit-btn"
                      onClick={() => onEdit(eq)}
                    >
                      Edit
                    </button>
                    <button 
                      className="delete-btn"
                      onClick={() => onDelete(eq.id)}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

export default EquipmentTable;
